ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  "query": {
    "find": p('mongo-sapi-services.orders.collection-order-completed'),
    "filter": {
      "Servicio_Tramite.Id_Cuenta_Servicio": attributes.uriParams.idServiceAccount default vars.idServiceAccount default vars.inputPayload.body.idServiceAccount
    }
  }
}

ee:variables.ee:set-variable:
%dw 2.0
output application/json

var firstResult = vars.resultDB[0] default {}

var mayorista = firstResult.Caracteristica_Orden filter ($.Caracteristica == "MAYORISTA")
---
((mayorista[0].Valor default "") ++ "_" ++ (firstResult.Numero_Orden default "")) == (vars.result default "")

%dw 2.0
output application/java
var order = (vars.resultDB default [])[0] default {}
var tipoTramite = upper(order.Tramite.Tipo_Tramite default "")
var estadoComercial = upper(order.Estado_Orden_Comercial.Codigo default "")
---
(tipoTramite == upper(p('interaction-params.transactType'))) and (estadoComercial == upper(p('mongo-sapi-services.orders.commercial-status-completed')))
